<?php require_once 'config.php';require_login();$u=current_user();if($u['role']==='admin')redirect('admin.php');if($u['role']==='trainer')redirect('trainer.php');$pageTitle='My dashboard';$s=db()->prepare("SELECT c.*,e.enrolled_at,e.status enrollment_status FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC");$s->execute([$u['id']]);$courses=$s->fetchAll();$completed=count(array_filter($courses,fn($c)=>$c['enrollment_status']==='completed'));$s=db()->prepare('SELECT COUNT(*) FROM assessment_attempts WHERE user_id=?');$s->execute([$u['id']]);$attempts=(int)$s->fetchColumn();$s=db()->prepare('SELECT * FROM announcements ORDER BY created_at DESC LIMIT 3');$s->execute();$announcements=$s->fetchAll();require 'includes/header.php'; ?>
<section class="dashboard-welcome"><div><span class="eyebrow">YOUR LEARNING SPACE</span><h1>Welcome back, <em><?= e(explode(' ',$u['name'])[0]) ?>.</em></h1><p>Keep showing up. Every step forward counts.</p></div><a class="btn btn-primary" href="courses.php">Find a course +</a></section><section class="stats-grid"><div class="stat-card"><span class="stat-icon blue">▤</span><span>Enrolled courses</span><strong><?= count($courses) ?></strong><small>Your active learning paths</small></div><div class="stat-card"><span class="stat-icon green">✓</span><span>Completed courses</span><strong><?= $completed ?></strong><small>Milestones reached</small></div><div class="stat-card"><span class="stat-icon orange">✎</span><span>Assessments attempted</span><strong><?= $attempts ?></strong><small>Keep testing your skills</small></div></section><section class="section dashboard-section"><div class="section-heading"><div><span class="eyebrow">KEEP LEARNING</span><h2>My courses</h2></div><a class="text-link" href="courses.php">Explore more →</a></div><?php if($courses): ?><div class="course-grid"><?php foreach($courses as $c): ?><article class="course-card"><div class="course-cover cover-<?= e($c['category']?:'general') ?>"><span><?= e($c['icon']?:'✦') ?></span><small><?= e($c['category']?:'Learning path') ?></small></div><div class="course-content"><h3><?= e($c['title']) ?></h3><p><?= e(mb_strimwidth($c['description']??'',0,100,'…')) ?></p><div class="course-meta"><span class="status-pill"><?= e(ucfirst($c['enrollment_status'])) ?></span><a href="course.php?id=<?= (int)$c['id'] ?>">Continue →</a></div></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span>✦</span><h3>Your learning journey is ready</h3><p>Enroll in a course to see your resources and assessments here.</p><a class="btn btn-primary" href="courses.php">Explore courses →</a></div><?php endif; ?></section><section class="section dashboard-section"><div class="section-heading"><div><span class="eyebrow">STAY IN THE LOOP</span><h2>Latest announcements</h2></div><a class="text-link" href="announcements.php">All announcements →</a></div><?php if($announcements): ?><div class="announcement-list"><?php foreach($announcements as $a): ?><article><span class="announcement-mark">✦</span><div><h3><?= e($a['title']) ?></h3><p><?= e($a['body']) ?></p><small><?= e(date('d M Y',strtotime($a['created_at']))) ?></small></div></article><?php endforeach; ?></div><?php else: ?><p class="muted">No announcements yet.</p><?php endif; ?></section><?php require 'includes/footer.php'; ?>
